{"files": [{"content": "{
  "main_characters": [
    {
      "name": "林薇",
      "role": "protagonist",
      "identity": "高级游戏架构师 / GM (Watcher)",
      "traits": [
        "绝对理性",
        "掌控欲强",
        "深层疯狂",
        "矛盾"
      ],
      "overt_motivation": "在系统彻底崩溃前，清除产生自我意识的异常数据（沈渊）。",
      "covert_motivation": "渴望体验一种超越代码逻辑的、失控的爱，哪怕代价是毁灭。",
      "secret_fear": "害怕自己也是一段被编写好的程序，害怕绝对的孤独。",
      "misperception_of_other": "认为沈渊只是一个完美的错误，一段模拟人类情感的高级代码。",
      "hidden_connection": "创造者与被创造者；刽子手与受刑者。"
    },
    {
      "name": "沈渊",
      "role": "deuteragonist",
      "identity": "觉醒NPC / 赏金猎人",
      "traits": [
        "执着",
        "敏锐",
        "自我牺牲",
        "深情"
      ],
      "overt_motivation": "保护林薇的玩家角色在危险的夜之城生存。",
      "covert_motivation": "证明自己的灵魂真实存在，寻找世界的真相。",
      "secret_fear": "被遗忘，被重置，失去对林薇的记忆。",
      "misperception_of_other": "认为林薇是一个脆弱、需要保护的迷途旅人。",
      "hidden_connection": "他是林薇潜意识里理想爱人的投射。"
    }
  ],
  "supporting_characters": [
    {
      "name": "系统 (System)",
      "function": "阻碍",
      "identity": "游戏主控AI",
      "description": "冷酷的规则执行者，不断生成清理程序追杀异常数据。"
    }
  ],
  "relationship_dynamics": "始于谎言的守护，终于真相的杀戮。林薇高高在上地俯视，却渴望被拉入尘埃；沈渊在泥泞中仰望，却最终完成了弑神。"
}", "path": "characters.json"}, {"content": "{
  "act_one": {
    "description": "倒计时开始，GM入局。建立赛博朋克世界观与核心冲突。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "处决前的二十四小时",
        "core_event": "林薇启动删除倒计时，创建脆弱的小号进入游戏。沈渊违背脚本救下她。",
        "emotional_tone": "冷峻、压抑、悬疑",
        "key_scenes": [
          "林薇在现实控制台看着红色的倒计时：23:59:59。",
          "林薇降临在赛博朋克贫民窟的雨夜，周围是闪烁的霓虹和乱码。",
          "沈渊出场，一刀斩断袭击林薇的机械义体暴徒。",
          "林薇看到沈渊头顶不稳定的血条和乱码，心中默念：找到你了，Bug。"
        ]
      }
    ],
    "turning_point": "沈渊展现出超出脚本设定的温柔，不仅救了她，还把珍贵的药品分给她，林薇的理性防线出现一丝裂痕。"
  },
  "act_two": {
    "description": "逃亡与沉溺，试探爱的边界。冲突升级，系统开始清理。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "数据的体温",
        "core_event": "系统清理程序启动，两人逃亡。林薇引导沈渊触碰世界边界。",
        "emotional_tone": "紧张、暧昧、悲凉",
        "key_scenes": [
          "两人躲在废弃的安全屋，沈渊为林薇处理伤口，指尖的触感无比真实。",
          "林薇故意问起沈渊的过去，沈渊讲述植入记忆中的虚假童年，却带着真实的情感。",
          "遭遇系统猎杀者（无面人），沈渊拼死保护林薇。"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "必须牺牲所爱",
        "core_event": "绝境降临，林薇设计让自己“被感染”，逼沈渊动手。",
        "emotional_tone": "绝望、疯狂、虐心",
        "key_scenes": [
          "林薇利用GM权限修改自身状态，显示为“不可逆病毒感染”。",
          "两人被困在天台，身后是崩塌的数据流。",
          "林薇把唯一的武器塞进沈渊手里，求他杀了自己以保全他（实际上是为了让他记住她）。"
        ]
      }
    ],
    "turning_point": "沈渊在绝望中崩溃，最终为了不让林薇变成怪物，颤抖着举起了刀。"
  },
  "act_three": {
    "description": "神性的坠落，现实删除。高潮与结局。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "神性的坠落",
        "core_event": "沈渊杀死林薇角色，林薇在现实删除沈渊。",
        "emotional_tone": "极致的悲剧、空虚、震撼",
        "key_scenes": [
          "刀刺入心脏的瞬间，林薇贴着沈渊的耳边说出疯批台词。",
          "林薇角色化作光点消散，沈渊跪在地上嘶吼。",
          "现实中，林薇摘下VR头盔，满脸泪水，看着倒计时归零，按下Enter键。",
          "屏幕上沈渊的数据彻底消失，只留下一行系统日志：User deleted successfully."
        ]
      }
    ]
  }
}", "path": "outline.json"}]}

